import {seed} from './demo-data.mjs';
import {uid,today,money,number,escapeHtml as e,taskProgress,availableStock,stockMove,receiveOrder,publishUpdate,decideApproval,clientProjection,clientInvite} from './model.mjs';

const STORAGE_KEY='simworx-project-hub-demo-v1';
function load(){try{const v=JSON.parse(localStorage.getItem(STORAGE_KEY));if(v?.version===1)return v;}catch{}return seed()}
let data=load();
const ui={page:'overview',project:'p1',projectTab:'structure',dept:'All',taskView:'board',clientOrg:'noah',clientProject:'p1',clientTab:'updates',customerDetail:null,query:'',modal:null};
const persist=()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));}catch{toast('Local storage is full; changes may not persist.',true)}};
const findProject=id=>data.projects.find(x=>x.id===id);
const findOrg=id=>data.organizations.find(x=>x.id===id);
const findPart=id=>data.parts.find(x=>x.id===id);
const projectOrg=p=>findOrg(p.orgId);
const day=s=>{if(!s)return 'Not set';const d=new Date(String(s).slice(0,10)+'T12:00:00Z');return Number.isNaN(+d)?String(s):d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})};
const pct=n=>Math.max(0,Math.min(100,Math.round(Number(n)||0)));
const stateColor=s=>/done|received|approved|complete/i.test(s)?'green':/blocked|overdue|rejected/i.test(s)?'red':/progress|inspection|awaiting|pending|ready/i.test(s)?'amber':/design|draft/i.test(s)?'purple':'blue';
const badge=(s,c=stateColor(s))=>`<span class="pill ${c}">${e(s)}</span>`;
const meter=(value,variant='')=>`<div class="meter ${variant}"><i style="width:${pct(value)}%"></i></div>`;
const chip=(org)=>`<span class="customer-mini" style="background:${e(org?.accent||'#6f57d9')}">${e(org?.logo||'?')}</span>`;
const glyph=kind=>`<svg viewBox="0 0 120 95" fill="none" aria-hidden="true"><ellipse cx="60" cy="77" rx="49" ry="7" fill="#fff" opacity=".11"/><path d="M18 63V43l15-16h54l15 16v20H18Z" stroke="#9cc7f1" stroke-width="3" fill="#2d5173" opacity=".95"/><path d="M33 27v36M87 27v36M18 44h84M50 27v37M70 27v37" stroke="#a9ccf5" stroke-width="2"/><path d="M22 65h76M29 16l9-7h44l9 7" stroke="#e2f1ff" stroke-width="2"/>${kind==='motion'?'<path d="m21 80 18-12h42l18 12M36 77v-9M84 77v-9" stroke="#e9d5ff" stroke-width="3"/>':''}</svg>`;
const heroArt=()=>`<svg viewBox="0 0 420 320" fill="none" aria-hidden="true"><g stroke="#b6d6f6" stroke-width="2" opacity=".7"><ellipse cx="220" cy="238" rx="165" ry="31"/><path d="M75 220V130l50-68h190l50 68v90H75Z" fill="#3574b0" fill-opacity=".1"/><path d="M125 62v159M315 62v159M75 130h290M173 62v161M268 62v161"/><path d="M78 217h285M77 174h285M125 62l48 68m142-68-47 68"/><path d="M74 219 42 241m322-23 33 23m-257-11 0 45m143-45 0 45"/></g><g fill="#87bef0" opacity=".25"><rect x="143" y="146" width="56" height="27" rx="4"/><rect x="221" y="146" width="56" height="27" rx="4"/><circle cx="171" cy="160" r="10"/><circle cx="249" cy="160" r="10"/></g></svg>`;
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',projects:'<rect x="3" y="6" width="18" height="14" rx="2"/><path d="M3 10h18M7 6V4h5l2 2"/>',tasks:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 12 3 3 6-7"/>',purchasing:'<path d="M4 5h2l2 11h11l2-8H7M10 21h.01M18 21h.01"/>',inventory:'<path d="m12 2 9 5-9 5-9-5 9-5Zm-9 5v10l9 5 9-5V7M12 12v10"/>',customers:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm10-1a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87"/>',client:'<path d="M4 4h16v16H4zM4 9h16M9 20V9"/>',finance:'<path d="M3 3v18h18M7 15l4-4 3 2 5-7"/>',reports:'<path d="M4 20V10m5 10V4m5 16v-7m5 7V7M2 20h20"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a2 2 0 0 0 .4 2.2l.1.1-2 2-1-.6a2 2 0 0 0-2.2-.1l-.3.2-.4 1.2h-3l-.4-1.2a2 2 0 0 0-2.2-.1l-1 .6-2-2 .7-1a2 2 0 0 0-.2-2.2l-1.2-.5v-3l1.2-.4a2 2 0 0 0 .2-2.2l-.7-1 2-2 1 .7a2 2 0 0 0 2.2-.2l.4-1.2h3l.4 1.2a2 2 0 0 0 2.2.2l1-.7 2 2-.7 1a2 2 0 0 0-.1 2.2l1.2.4v3z"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/>',moon:'<path d="M20 15A8 8 0 0 1 9 4 8 8 0 1 0 20 15Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',chevron:'<path d="m9 18 6-6-6-6"/>',down:'<path d="m6 9 6 6 6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',external:'<path d="M13 5h6v6M19 5l-9 9M19 13v6H5V5h6"/>',file:'<path d="M6 2h9l5 5v15H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2ZM14 2v6h6"/>',message:'<path d="M20 16a3 3 0 0 1-3 3H7l-4 3V6a3 3 0 0 1 3-3h11a3 3 0 0 1 3 3v10Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',shield:'<path d="M12 2 3 6v6c0 6 4 9 9 10 5-1 9-4 9-10V6l-9-4Z"/><path d="m8 12 3 3 5-6"/>',warehouse:'<path d="m3 9 9-6 9 6v12H3V9Zm5 12v-9h8v9M3 9h18"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',refresh:'<path d="M4 11a8 8 0 0 1 13-6l3 3M20 4v4h-4M20 13a8 8 0 0 1-13 6l-3-3m0 4v-4h4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v4h16v-4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>'};
const ico=(n,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const button=(label,action='',variant='',attr='')=>`<button type="button" class="btn ${variant}" data-action="${action}" ${attr}>${label}</button>`;
const head=(title,desc,actions='')=>`<div class="page-heading"><div><h1>${e(title)}</h1><p>${e(desc)}</p></div><div class="heading-actions">${actions}</div></div>`;
const card=(title,body,actions='',subtitle='')=>`<div class="card"><div class="card-head"><div><h2>${e(title)}</h2>${subtitle?`<div class="card-sub">${e(subtitle)}</div>`:''}</div>${actions}</div>${body}</div>`;
const projectSelect=(selected,attr='')=>`<select class="filter-select" ${attr}>${data.projects.map(p=>`<option value="${e(p.id)}" ${selected===p.id?'selected':''}>${e(p.code)} · ${e(p.name)}</option>`).join('')}</select>`;
const customerSelect=(selected,attr='')=>`<select class="filter-select" ${attr}>${data.organizations.map(o=>`<option value="${e(o.id)}" ${selected===o.id?'selected':''}>${e(o.name)}</option>`).join('')}</select>`;
const projectTitle=p=>`<div class="project-cell"><div class="project-glyph ${p.template==='DA62'?'diamond':p.template==='Motion Upgrade'?'motion':'king'}">${glyph(p.template==='Motion Upgrade'?'motion':'')}</div><div><div class="project-title">${e(p.name)}</div><div class="subtle mono">${e(p.code)}</div></div></div>`;
const audit=(action,detail,actor='Sim-Worx Admin')=>data.audit.unshift({id:uid('audit'),action,detail,actor,at:new Date().toISOString()});
const notify=text=>data.notifications.unshift({id:uid('note'),text,date:today(),read:false});
let toastTimer;
function toast(msg,error=false){const old=document.querySelector('.toast');if(old)old.remove();const t=document.createElement('div');t.className=`toast ${error?'error':''}`;t.textContent=msg;document.body.appendChild(t);clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.remove(),4100)}
function render(){
  const labels={overview:'Dashboard',projects:'Projects',tasks:'Production jobs',purchasing:'Purchasing',inventory:'Inventory',customers:'Customers & access',client:'Customer portal',finance:'Project financials',reports:'Reports & progress',settings:'Settings'};
  const nav=[['overview','Overview'],['projects','Projects'],['tasks','Workshop & office'],['purchasing','Purchasing'],['inventory','Inventory'],['customers','Customers & access'],['client','Client portal preview'],['finance','Financials'],['reports','Reports'],['settings','Settings']];
  const navHtml=nav.map(([id,label],idx)=>`${idx===0||idx===3||idx===6||idx===7?`<div class="nav-group-label">${idx===0?'WORKSPACE':idx===3?'OPERATIONS':idx===6?'COLLABORATION':'CONTROL & INSIGHT'}</div>`:''}<button class="nav-link ${ui.page===id?'active':''}" data-action="nav" data-id="${id}" aria-current="${ui.page===id?'page':'false'}">${ico(id)}<span>${label}</span>${id==='client'?'<span class="count-dot">↗</span>':''}</button>`).join('');
  const title=labels[ui.page]||'Project Hub';
  document.body.classList.toggle('dark',data.settings.theme==='dark');
  document.getElementById('app').innerHTML=`<div class="app-shell">
    <aside class="sidebar"><div class="brand"><div class="brand-gem">${ico('warehouse',23)}</div><div class="brand-name">SIM-WORX<span>PROJECT HUB</span></div></div><nav>${navHtml}</nav><div class="sidebar-bottom"><div class="workspace-mark"><div class="avatar">SW</div><div><b>Sim-Worx Team</b><small>Local demonstration</small></div></div></div></aside>
    <div class="main"><header class="topbar"><div><div class="top-title">${e(title)}</div><div class="top-sub">Plan, build, deliver — all in one place</div></div><div class="top-actions"><span class="demo-ribbon">DEMO · NOT LIVE</span><label class="top-search">${ico('search')}<input id="global-search" placeholder="Search projects..." autocomplete="off" aria-label="Search projects" /></label><button class="circle-btn" data-action="theme" aria-label="Toggle colour theme" title="Light / dark mode">${ico(data.settings.theme==='light'?'moon':'sun')}</button><button class="circle-btn" data-action="notifications" aria-label="Notifications" title="Notifications">${ico('bell')}</button><div class="avatar" title="Sim-Worx Administrator">SW</div></div></header>
    <main class="content">${pageContent()}</main></div></div>${ui.modal?modalContent():''}`;
  bindGlobalSearch();
}
function bindGlobalSearch(){const el=document.getElementById('global-search');if(!el)return;el.value=ui.query;el.addEventListener('keydown',ev=>{if(ev.key==='Enter'){const q=el.value.trim().toLowerCase();const p=data.projects.find(p=>`${p.name} ${p.code} ${projectOrg(p)?.name}`.toLowerCase().includes(q));if(p){ui.project=p.id;ui.page='projects';ui.projectTab='structure';ui.query='';render();}else toast('No matching project found',true)}})}
function pageContent(){switch(ui.page){case 'overview':return overview();case 'projects':return projectsPage();case 'tasks':return tasksPage();case 'purchasing':return purchasingPage();case 'inventory':return inventoryPage();case 'customers':return customersPage();case 'client':return clientPage();case 'finance':return financePage();case 'reports':return reportsPage();case 'settings':return settingsPage();default:return overview()}}
function overview(){
  const active=data.projects.filter(p=>p.status!=='Delivered');const avg=Math.round(active.reduce((a,p)=>a+taskProgress(p.id,data.tasks),0)/(active.length||1));
  const pending=data.approvals.filter(a=>a.status==='Pending').length,blocked=data.tasks.filter(t=>t.status==='Blocked').length;
  const kpis=[['Active projects',active.length,'projects','Across '+data.organizations.length+' customers'],['Internal progress',avg+'%','reports','Weighted job status snapshot'],['Open production jobs',data.tasks.filter(t=>!['Done','Cancelled'].includes(t.status)).length,'tasks','Office & workshop tasks'],['Client approvals',pending,'shield','Decisions awaiting clients']];
  const kpiHtml=kpis.map(([label,value,icon,note])=>`<div class="kpi"><div><div class="kpi-label">${e(label)}</div><div class="kpi-value mono">${e(value)}</div><div class="kpi-note">${e(note)}</div></div><div class="kpi-icon">${ico(icon,23)}</div></div>`).join('');
  const rows=data.projects.map(p=>`<tr><td class="clickable" data-action="project-open" data-id="${p.id}">${projectTitle(p)}</td><td><div style="display:flex;gap:7px;align-items:center">${chip(projectOrg(p))}<b>${e(projectOrg(p).name)}</b></div></td><td><div class="progress-line">${meter(taskProgress(p.id,data.tasks))}<span class="mono">${taskProgress(p.id,data.tasks)}%</span></div></td><td>${badge(p.status)}</td><td class="subtle">${day(p.due)}</td><td>${button(ico('chevron'),'project-open','small',`data-id="${p.id}" aria-label="Open ${e(p.name)}"`)}</td></tr>`).join('');
  const pipelines=[['Engineering','Office',data.tasks.filter(t=>t.department==='Office'&&t.status!=='Done').length,'projects'],['Workshop floor','Workshop',data.tasks.filter(t=>t.department==='Workshop'&&t.status!=='Done').length,'inventory'],['Procurement','Purchasing',data.tasks.filter(t=>t.department==='Purchasing'&&t.status!=='Done').length,'purchasing'],['Quality control','Quality',data.tasks.filter(t=>t.department==='Quality'&&t.status!=='Done').length,'shield']];
  return head('Good morning, Sim-Worx','Your manufacturing and delivery overview for '+day(today()),button(`${ico('plus')} New project`,'open-project-modal','primary'))+
  `<div class="kpis">${kpiHtml}</div><div class="grid-main"><div class="column">${card('Project portfolio',`<div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Customer</th><th>Progress</th><th>Status</th><th>Delivery</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`,button('View projects','nav','small',`data-id="projects"`),'Live overview from local demo records')}
  ${card('Department workload',`<div class="card-body" style="padding-top:0">${pipelines.map(([title,dept,count,icon])=>`<div class="pipeline-item"><div class="pipe-icon">${ico(icon)}</div><div class="pipe-main"><strong>${title}</strong><small>${dept} team · outstanding actions</small></div><span class="pipe-count mono">${count}</span>${button(ico('chevron'),'department-open','small',`data-id="${dept}"`)}</div>`).join('')}</div>`,'','See who needs to do what next')}</div>
  <div class="column"><div class="hero-card"><div class="hero-content"><div class="eyebrow">PROJECT SPOTLIGHT · ${e(data.projects[0].code)}</div><h2>${e(data.projects[0].name)}</h2><p>From engineering drawings to a finished simulator. Track every build stage in one connected workspace.</p>${button('Open project '+ico('arrow'),'project-open','primary',`data-id="p1"`)}</div><div class="hero-art">${heroArt()}</div></div>
  ${card('Needs your attention',`<div class="card-body" style="padding-top:0"><div class="pipeline-item"><div class="pipe-icon">${ico('shield')}</div><div class="pipe-main"><strong>${pending} customer approvals waiting</strong><small>Drawings and milestone sign-offs</small></div>${badge('Action needed','amber')}</div><div class="pipeline-item"><div class="pipe-icon">${ico('clock')}</div><div class="pipe-main"><strong>${blocked} blocked production job${blocked===1?'':'s'}</strong><small>Check materials and dependencies</small></div>${badge('Review','red')}</div><div class="pipeline-item"><div class="pipe-icon">${ico('inventory')}</div><div class="pipe-main"><strong>${data.parts.filter(p=>availableStock(p)<=p.min).length} parts near reorder level</strong><small>Available stock vs minimum</small></div>${badge('Monitor','amber')}</div></div>`)}
  ${card('Recent activity',`<div class="card-body" style="padding-top:0"><div class="activity">${data.audit.slice(0,4).map(a=>`<div class="activity-row"><strong>${e(a.action)}</strong><span>${e(a.detail)}<br>${e(a.actor)} · ${day(a.at)}</span></div>`).join('')}</div></div>`)}</div></div>`;
}
function projectsPage(){const p=findProject(ui.project);const list=data.projects.map(x=>`<tr><td>${projectTitle(x)}</td><td>${e(projectOrg(x).name)}</td><td>${badge(x.status)}</td><td><div class="progress-line">${meter(taskProgress(x.id,data.tasks))}<span>${taskProgress(x.id,data.tasks)}%</span></div></td><td>${day(x.due)}</td><td>${button('Open '+ico('chevron'),'project-open','small',`data-id="${x.id}"`)}</td></tr>`).join('');
  return head('Projects','A single source of truth for every simulator build.',button(`${ico('plus')} Create project`,'open-project-modal','primary'))+`<div class="card" style="margin-bottom:19px"><div class="card-head"><h2>All projects</h2><span class="subtle">${data.projects.length} active records</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Customer</th><th>Status</th><th>Internal completion</th><th>Target delivery</th><th></th></tr></thead><tbody>${list}</tbody></table></div></div>${p?projectDetail(p):''}`;
}
function projectDetail(p){const org=projectOrg(p);const nav=['structure','bom','documents','publishing'];const labels=['Work breakdown','Bill of materials','Documents','Client publishing'];const contents={structure:projectStructure(p),bom:projectBom(p),documents:projectDocuments(p),publishing:projectPublishing(p)};
 return `<div id="project-detail" class="project-hero"><div class="project-hero-art">${glyph(p.template)}</div><div class="project-meta"><div class="eyebrow">${e(p.code)} · ${e(org.name)}</div><h2>${e(p.name)}</h2><p>${e(p.description)}</p><div class="meta-row"><div>Project lead<strong>${e(p.lead)}</strong></div><div>Current phase<strong>${e(p.phase)}</strong></div><div>Target delivery<strong>${day(p.due)}</strong></div><div>Internal progress<strong>${taskProgress(p.id,data.tasks)}%</strong></div></div></div></div><div class="card"><div class="tabs">${nav.map((n,i)=>`<button data-action="project-tab" data-id="${n}" class="${ui.projectTab===n?'active':''}">${labels[i]}</button>`).join('')}</div>${contents[ui.projectTab]||contents.structure}</div>`;
}
function projectStructure(p){const s=data.sections.filter(s=>s.projectId===p.id);return `<div class="toolbar"><div class="subtle">Project → Sections → Jobs → Tasks</div><div class="spacer"></div>${button(`${ico('plus')} Add job`,'open-task-modal','small',`data-project="${p.id}"`)}</div><div class="hierarchy">${s.map(sec=>{const tasks=data.tasks.filter(t=>t.sectionId===sec.id);const done=tasks.length?Math.round(tasks.filter(t=>t.status==='Done').length/tasks.length*100):0;return `<div class="hierarchy-section"><div class="hierarchy-section-title"><div style="display:flex;gap:9px;align-items:center">${ico('projects')} ${e(sec.name)} <span class="subtle">${tasks.length} jobs</span></div><div style="display:flex;gap:10px;align-items:center;width:150px">${meter(done)}<span>${done}%</span></div></div><div class="hierarchy-tasks">${tasks.length?tasks.map(t=>taskItem(t)).join(''):'<div class="subtle" style="padding:12px">No tasks in this section yet.</div>'}</div></div>`}).join('')}</div>`;}
function taskItem(t){return `<div class="task-item"><button class="task-bullet ${t.status==='Done'?'done':''}" data-action="toggle-task" data-id="${t.id}" aria-label="Toggle task completion">${t.status==='Done'?ico('check',12):''}</button><div class="details"><strong>${e(t.title)}</strong><small>${e(t.assignee)} · Due ${day(t.due)}</small></div><span class="tag ${e(t.department.toLowerCase())}">${e(t.department)}</span>${badge(t.status)}</div>`}
function projectBom(p){const rows=data.bom.filter(b=>b.projectId===p.id);return `<div class="toolbar"><span class="subtle">Project-specific quantities and linked stock</span><div class="spacer"></div>${button('Manage inventory '+ico('external'),'nav','small',`data-id="inventory"`)}</div><div class="table-wrap"><table class="table"><thead><tr><th>Part number</th><th>Description</th><th>Required</th><th>Reserved</th><th>Issued</th><th>To source</th></tr></thead><tbody>${rows.map(b=>{const x=findPart(b.partId);return `<tr><td><strong class="mono">${e(x?.code)}</strong></td><td>${e(x?.name)}</td><td>${number(b.required)}</td><td>${number(b.reserved)}</td><td>${number(b.issued)}</td><td>${badge(String(Math.max(0,b.required-b.reserved-b.issued)),b.required>b.reserved+b.issued?'amber':'green')}</td></tr>`}).join('')||'<tr><td colspan="6" class="subtle">No BOM items assigned</td></tr>'}</tbody></table></div>`}
function projectDocuments(p){const docs=data.documents.filter(d=>d.projectId===p.id);return `<div class="toolbar"><span class="subtle">Revision-aware document register · demo metadata only</span><div class="spacer"></div>${button(`${ico('plus')} Add document`,'open-document-modal','small',`data-project="${p.id}"`)}</div><div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>Revision</th><th>Type</th><th>Visibility</th><th>Updated</th></tr></thead><tbody>${docs.map(d=>`<tr><td>${ico('file')} <strong>${e(d.title)}</strong></td><td>${e(d.rev)}</td><td>${e(d.type)}</td><td>${badge(d.visibility==='customer'?'Published':'Internal',d.visibility==='customer'?'green':'gray')}</td><td>${day(d.date)}</td></tr>`).join('')||'<tr><td colspan="5" class="subtle">No documents</td></tr>'}</tbody></table></div>`}
function projectPublishing(p){const u=data.updates.filter(x=>x.projectId===p.id);return `<div class="toolbar"><div class="subtle">Never automatically expose internal jobs to customers</div><div class="spacer"></div>${button(`${ico('plus')} Draft update`,'open-update-modal','small',`data-project="${p.id}"`)}</div><div class="card-body" style="padding-top:4px">${u.map(x=>`<div class="approval-row"><div><strong>${e(x.title)}</strong><small>${e(x.kind)} · ${e(x.description)}</small></div><div class="row-actions">${badge(x.status==='published'?'Published':'Draft',x.status==='published'?'green':'purple')}${x.status==='draft'?button('Publish','publish','small primary',`data-id="${x.id}"`):''}</div></div>`).join('')||'<div class="empty">No updates yet</div>'}<p class="form-hint">Publishing here updates only the local demo customer preview. Production requires a separate allowlisted customer representation and verified permissions.</p></div>`}
function tasksPage(){const project=ui.taskProject||'all';const filtered=data.tasks.filter(t=>(ui.dept==='All'||t.department===ui.dept)&&(project==='all'||t.projectId===project));
  const projectFilter=`<select class="filter-select" data-filter="taskProject"><option value="all">All projects</option>${data.projects.map(p=>`<option value="${p.id}" ${project===p.id?'selected':''}>${e(p.code)} — ${e(p.name)}</option>`).join('')}</select>`;
  const deptFilter=`<select class="filter-select" data-filter="dept">${['All','Office','Workshop','Purchasing','Quality'].map(d=>`<option ${ui.dept===d?'selected':''}>${d}</option>`).join('')}</select>`;
  const headTools=`${button(`${ico('plus')} New job`,'open-task-modal','primary')}`;
  const cols=[['Backlog','Backlog'],['Ready','Ready'],['In progress','In progress'],['Blocked','Blocked'],['Inspection','Inspection'],['Done','Done']];
  const board=`<div class="kanban">${cols.map(([status,label])=>{const list=filtered.filter(t=>t.status===status);return `<div class="kanban-col"><div class="kanban-head"><strong>${label}</strong><span class="pill no-dot gray">${list.length}</span></div>${list.map(t=>`<div class="task-card"><strong>${e(t.title)}</strong><p>${e(findProject(t.projectId)?.code)} · ${e(t.assignee)}</p><div class="task-footer"><span class="tag ${e(t.department.toLowerCase())}">${e(t.department)}</span><select class="filter-select" style="max-width:120px;min-height:29px;padding:5px" data-task-status="${t.id}" aria-label="Change task status">${cols.map(([val])=>`<option value="${val}" ${t.status===val?'selected':''}>${val}</option>`).join('')}</select></div></div>`).join('')||'<div class="subtle" style="padding:12px 4px">No jobs</div>'}</div>`}).join('')}</div>`;
  const rows=filtered.map(t=>`<tr><td><b>${e(t.title)}</b><div class="subtle">${e(findProject(t.projectId)?.code)}</div></td><td>${e(t.department)}</td><td>${e(t.assignee)}</td><td>${badge(t.status)}</td><td>${day(t.due)}</td><td><select data-task-status="${t.id}" class="filter-select" style="max-width:150px">${cols.map(([v])=>`<option value="${v}" ${t.status===v?'selected':''}>${v}</option>`).join('')}</select></td></tr>`).join('');
  return head('Workshop & office jobs','Assignable work across engineering, production, purchasing and quality.',headTools)+`<div class="card"><div class="toolbar">${projectFilter}${deptFilter}<div class="spacer"></div><div class="segmented">${button('Board','task-board',`small ${ui.taskView==='board'?'active':''}`)}${button('List','task-list',`small ${ui.taskView==='list'?'active':''}`)}</div></div><div class="card-body">${ui.taskView==='board'?board:`<div class="table-wrap"><table class="table"><thead><tr><th>Job</th><th>Department</th><th>Assigned</th><th>Status</th><th>Due</th><th>Update</th></tr></thead><tbody>${rows}</tbody></table></div>`}</div></div>`;
}
function purchasingPage(){const orders=data.orders,open=orders.filter(o=>o.status!=='Received');const total=orders.reduce((s,o)=>s+o.items.reduce((x,l)=>x+Number(l.quantity)*Number(l.unitCost),0),0);
  return head('Purchasing','Supplier orders, open commitments and materials due for the workshop.',button(`${ico('plus')} New purchase order`,'open-po-modal','primary'))+`<div class="kpis"><div class="kpi"><div><div class="kpi-label">Purchase orders</div><div class="kpi-value">${orders.length}</div><div class="kpi-note">All tracked orders</div></div><div class="kpi-icon">${ico('purchasing')}</div></div><div class="kpi"><div><div class="kpi-label">Open orders</div><div class="kpi-value">${open.length}</div><div class="kpi-note">Awaiting goods</div></div><div class="kpi-icon">${ico('clock')}</div></div><div class="kpi"><div><div class="kpi-label">Order value</div><div class="kpi-value" style="font-size:23px">${money(total)}</div><div class="kpi-note">Demonstration purchases</div></div><div class="kpi-icon">${ico('finance')}</div></div><div class="kpi"><div><div class="kpi-label">Partially received</div><div class="kpi-value">${orders.filter(o=>o.status==='Part received').length}</div><div class="kpi-note">Outstanding balances</div></div><div class="kpi-icon">${ico('inventory')}</div></div></div>${card('Purchase order register',`<div class="table-wrap"><table class="table"><thead><tr><th>Order</th><th>Supplier</th><th>Allocated project</th><th>Value</th><th>Delivery status</th><th>Action</th></tr></thead><tbody>${orders.map(o=>`<tr><td><b>${e(o.code)}</b><div class="subtle">${day(o.date)}</div></td><td>${e(o.supplier)}</td><td><span class="subtle">${e(findProject(o.projectId)?.code)}</span></td><td>${money(o.items.reduce((x,l)=>x+l.quantity*l.unitCost,0))}</td><td>${badge(o.status)}</td><td>${o.status==='Received'?'<span class="subtle">All items received</span>':button('Receive remaining','receive-po','small',`data-id="${o.id}"`)}</td></tr>`).join('')}</tbody></table></div>`,'','Receiving an order adds its outstanding quantity into local demo stock')}`;
}
function inventoryPage(){const low=data.parts.filter(p=>availableStock(p)<=p.min);const rows=data.parts.map(p=>`<tr><td><strong class="mono">${e(p.code)}</strong><div class="subtle">${e(p.supplier)}</div></td><td><b>${e(p.name)}</b></td><td><span class="subtle">${e(p.location)}</span></td><td>${number(p.onHand)} ${e(p.unit)}</td><td>${number(p.reserved)}</td><td><strong class="${availableStock(p)<=p.min?'danger-text':'green-text'}">${number(availableStock(p))}</strong></td><td>${availableStock(p)<=p.min?badge('Reorder','amber'):badge('Healthy','green')}</td><td>${button('Move stock','stock-modal','small',`data-id="${p.id}"`)}</td></tr>`).join('');
  return head('Parts & inventory','A joined-up view of quantities, reservations, stores and shortages.',button(`${ico('plus')} Stock adjustment`,'stock-modal','primary'))+`<div class="kpis"><div class="kpi"><div><div class="kpi-label">Part SKUs</div><div class="kpi-value">${data.parts.length}</div><div class="kpi-note">Stock catalogue</div></div><div class="kpi-icon">${ico('inventory')}</div></div><div class="kpi"><div><div class="kpi-label">Below reorder level</div><div class="kpi-value">${low.length}</div><div class="kpi-note">Available stock</div></div><div class="kpi-icon">${ico('clock')}</div></div><div class="kpi"><div><div class="kpi-label">Reserved units</div><div class="kpi-value">${number(data.parts.reduce((s,p)=>s+p.reserved,0))}</div><div class="kpi-note">Allocated to projects</div></div><div class="kpi-icon">${ico('projects')}</div></div><div class="kpi"><div><div class="kpi-label">Inventory value</div><div class="kpi-value" style="font-size:22px">${money(data.parts.reduce((s,p)=>s+p.onHand*p.cost,0))}</div><div class="kpi-note">At reference demo cost</div></div><div class="kpi-icon">${ico('finance')}</div></div></div>${card('Stock register',`<div class="table-wrap"><table class="table"><thead><tr><th>Part</th><th>Description</th><th>Location</th><th>On hand</th><th>Reserved</th><th>Available</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`,'','Available stock = on hand − reservations')}<div style="height:18px"></div>${card('Recent movements',`<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Part</th><th>Movement</th><th>Quantity</th><th>By</th></tr></thead><tbody>${data.movements.slice(0,8).map(m=>`<tr><td>${day(m.date)}</td><td>${e(findPart(m.partId)?.code)}</td><td>${badge(m.type)}</td><td class="mono">${number(m.quantity)}</td><td>${e(m.actor)}</td></tr>`).join('')}</tbody></table></div>`)}`;
}
function customersPage(){const detail=ui.customerDetail?findOrg(ui.customerDetail):null;return head('Customers & access','Set up customer companies once, then grant projects and manage people.',button(`${ico('plus')} Add customer`,'open-customer-modal','primary'))+`<div class="customer-grid" style="margin-bottom:20px">${data.organizations.map(org=>{const projects=data.projects.filter(p=>p.orgId===org.id),members=data.members.filter(m=>m.orgId===org.id);return `<div class="org-card"><div class="org-header"><div class="org-logo" style="background:${e(org.accent)}">${e(org.logo)}</div><div><h3>${e(org.name)}</h3><span class="subtle">${e(org.contact)} · ${e(org.code)}</span></div></div><p>${projects.length} separate customer project${projects.length!==1?'s':''}, each with its own access controls.</p><div class="org-stats"><div><strong>${projects.length}</strong><span>Projects</span></div><div><strong>${members.length}</strong><span>People</span></div>${button('Manage '+ico('chevron'),'customer-detail','small',`data-id="${org.id}"`)}</div></div>`}).join('')}</div>${detail?customerDetail(detail):''}`}
function customerDetail(org){const members=data.members.filter(m=>m.orgId===org.id),projects=data.projects.filter(p=>p.orgId===org.id);return card(`${org.name} · customer team`, `<div class="toolbar"><span class="subtle">Customer admins can only delegate pre-granted project scopes in the future secure portal.</span><div class="spacer"></div>${button(`${ico('plus')} Add team member`,'invite-modal','small',`data-org="${org.id}"`)}</div><div class="table-wrap"><table class="table"><thead><tr><th>Person</th><th>Role</th><th>Project access</th><th>Status</th></tr></thead><tbody>${members.map(m=>`<tr><td><b>${e(m.name)}</b><div class="subtle">${e(m.email)}</div></td><td>${badge(m.role,'purple')}</td><td>${m.projects.map(id=>`<span class="tag">${e(findProject(id)?.code||id)}</span>`).join(' ')}</td><td>${badge(m.status||'Active','green')}</td></tr>`).join('')||'<tr><td colspan="4">No team members yet.</td></tr>'}</tbody></table></div><div class="card-body"><div class="subtle">Authorised projects: ${projects.map(p=>e(p.code)).join(', ')||'None'}</div></div>`);
}
function clientPage(){let projection=clientProjection(data,ui.clientOrg,ui.clientProject);if(!projection){ui.clientOrg=data.organizations[0]?.id;ui.clientProject=data.projects.find(p=>p.orgId===ui.clientOrg)?.id;projection=clientProjection(data,ui.clientOrg,ui.clientProject)}
  const org=projection?.organization,p=projection?.project;const options=projection?.projects||[];
  const selectors=`<div class="client-switch"><span class="pill purple">${ico('eye',13)} Client preview</span>${customerSelect(ui.clientOrg,'data-filter="clientOrg"')}<select class="filter-select" data-filter="clientProject">${options.map(q=>`<option value="${q.id}" ${p?.id===q.id?'selected':''}>${e(q.name)}</option>`).join('')}</select><div class="spacer"></div>${button(`${ico('plus')} Invite customer staff`,'invite-modal','small',`data-org="${org.id}"`)}</div>`;
  if(!p)return head('Customer portal','Preview exactly which types of information a customer should see.')+selectors+`<div class="empty">This customer has no projects.</div>`;
  const stages=['Discovery','Design','Manufacture','Assembly','Delivery'];let current=['Discovery','Engineering','Design','Manufacturing','Assembly','Commissioning','Testing','Delivery'].indexOf(p.phase);if(current<0)current=2;const phaseIndex=p.phase==='Manufacturing'?2:p.phase==='Assembly'?3:p.phase==='Delivery'?4:p.phase==='Engineering'?1:2;
  const preview=`<div class="client-banner" style="--customer:${e(org.accent)}"><div style="z-index:1;position:relative"><span class="client-badge">${e(org.name)} · PROJECT ACCESS</span><h2>${e(p.name)}</h2><p>${e(p.description)}</p><div class="timeline-steps">${stages.map((x,i)=>`<span class="timeline-step ${i<phaseIndex?'passed':i===phaseIndex?'current':''}"><b>${i<phaseIndex?ico('check',13):i+1}</b>${x}</span>`).join('')}</div></div><div class="client-delivery"><small>Target delivery</small><strong>${day(p.delivery)}</strong>${badge('In progress','green')}</div></div>`;
  const nav=[['updates','Progress updates'],['approvals','Approvals'],['files','Shared files'],['messages','Conversation'],['people','People & access']];
  const content=ui.clientTab==='updates'?clientUpdates(projection):ui.clientTab==='approvals'?clientApprovals(projection):ui.clientTab==='files'?clientFiles(projection):ui.clientTab==='messages'?clientMessages(projection):clientPeople(projection);
  return head('Customer portal preview','A separate, carefully curated view for each customer — not an internal dashboard.')+selectors+`<div class="client-notice">${ico('shield',15)} <strong>Demonstration preview only.</strong> Published records below are explicitly selected. The data is stored locally in this browser; production-grade customer isolation requires Supabase authentication and database security.</div><div class="client-shell" style="--customer:${e(org.accent)}">${preview}<div class="card"><div class="tabs">${nav.map(([key,label])=>`<button class="${ui.clientTab===key?'active':''}" data-action="client-tab" data-id="${key}">${label}${key==='approvals'?` <span class="count-dot">${projection.approvals.filter(a=>a.status==='Pending').length}</span>`:''}</button>`).join('')}</div><div class="card-body">${content}</div></div></div>`;
}
function clientUpdates(pr){return `<div class="grid-even" style="margin-bottom:6px"><div><div class="split-header"><b>Published project progress</b><b style="color:var(--green)">${pct(pr.project.publishedProgress)}%</b></div>${meter(pr.project.publishedProgress,'green')}<p class="form-hint">This number is a customer-approved snapshot, not the raw internal task average.</p></div><div><div class="split-header"><b>Latest milestones</b><span class="subtle">${pr.updates.length} published</span></div><div class="subtle">Updates and individual component status appear only after Sim-Worx publishes them.</div></div></div><h3 style="font:800 14px Manrope;margin:20px 0 12px">Progress journal</h3>${pr.updates.length?pr.updates.map(u=>`<div class="update-card"><div class="split-header">${badge(u.kind,'purple')}<span class="date">${day(u.publishedAt)}</span></div><h4>${e(u.title)}</h4><p>${e(u.description)}</p>${u.part?`<div class="subtle" style="margin-top:10px">Related component: ${e(u.part)}</div>`:''}</div>`).join(''):`<div class="empty">${ico('file')}<strong>Updates coming soon</strong><p>Published project milestones will appear here.</p></div>`}`}
function clientApprovals(pr){return pr.approvals.length?pr.approvals.map(a=>`<div class="approval-row"><div><strong>${e(a.title)}</strong><small>${e(a.kind)} · ${e(a.revision)} · Requested ${day(a.requested)}</small><small>Decision due ${day(a.due)}</small></div><div class="approval-actions">${a.status==='Pending'?`${button('Approve','decide-approval','small primary',`data-id="${a.id}" data-decision="Approved"`)}${button('Request changes','decide-approval','small',`data-id="${a.id}" data-decision="Changes requested"`)}`:badge(a.status)}</div></div>`).join('')+'<p class="form-hint">Demo decisions are recorded in your browser only. They are not digital signatures and do not contact Sim-Worx.</p>':'<div class="empty">No approval requests for this project.</div>'}
function clientFiles(pr){return `<div class="split-header"><div><b>Authorised project documents</b><div class="subtle" style="margin-top:4px">Only customer-published document metadata is displayed.</div></div>${button(`${ico('upload')} Add document`,'open-client-document-modal','small')}</div>${pr.documents.map(d=>`<div class="approval-row"><div style="display:flex;gap:12px;align-items:center">${ico('file',23)}<div><strong>${e(d.title)}</strong><small>${e(d.type)} · Revision ${e(d.rev)} · ${day(d.date)}</small></div></div>${badge('Shared','green')}</div>`).join('')||'<div class="empty">No shared documents</div>'}<p class="form-hint">File uploads and downloads will use private storage once the approved backend is connected. The demo does not save file bytes.</p>`}
function clientMessages(pr){return `<div class="column">${pr.messages.map(m=>`<div class="update-card" style="background:${m.author.startsWith('Sim-Worx')?'var(--violet2)':'var(--panel2)'}"><b style="font-size:11px">${e(m.author)}</b><span class="subtle" style="float:right">${day(m.at)}</span><p style="margin-top:10px">${e(m.text)}</p></div>`).join('')||'<p class="subtle">Start a conversation with the project team.</p>'}<form data-form="message" class="column"><div class="field"><label for="message-text">New message</label><textarea id="message-text" name="text" required placeholder="Ask the project team a question..."></textarea></div><button class="btn primary" type="submit" style="align-self:flex-end">${ico('message')} Send demo message</button></form></div>`}
function clientPeople(pr){return `<div class="split-header"><b>People with access to this project</b>${button(`${ico('plus')} Invite staff`,'invite-modal','small',`data-org="${pr.organization.id}"`)}</div><div class="table-wrap"><table class="table"><thead><tr><th>Person</th><th>Role</th><th>Scope</th></tr></thead><tbody>${pr.members.map(m=>`<tr><td><b>${e(m.name)}</b><div class="subtle">${e(m.email)}</div></td><td>${badge(m.role,'purple')}</td><td><span class="tag">This project</span></td></tr>`).join('')}</tbody></table></div><p class="form-hint">Production invites will require verified identity and server-enforced delegation ceilings. No invitations are actually sent from the demo.</p>`}
function financePage(){const total=(key)=>data.projects.reduce((sum,p)=>sum+Number(p[key]||0),0),revenue=total('contract'),spent=total('spent'),committed=total('committed'),forecast=revenue-spent-committed;
  const stats=[['Contract value',revenue,'Total project sales'],['Actual project costs',spent,'Entered expenditure'],['Committed orders',committed,'Outstanding forecast'],['Projected gross headroom',forecast,'Before unbudgeted future costs']];
  return head('Project financials','Internal management only — never included in the customer data projection.')+`<div class="client-notice">${ico('shield')} <strong>Private financial workspace.</strong> Figures are fictional demo values; real production budgets and supplier prices must be protected at the database and API layers.</div><div class="finance-stats">${stats.map(([label,v,note])=>`<div class="finance-stat"><span>${e(label)}</span><strong>${money(v)}</strong><small>${e(note)}</small></div>`).join('')}</div>${card('Project budget performance',`<div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Contract</th><th>Budget</th><th>Actual costs</th><th>Committed</th><th>Remaining budget</th></tr></thead><tbody>${data.projects.map(p=>{const remaining=p.budget-p.spent-p.committed;return `<tr><td><b>${e(p.name)}</b><div class="subtle">${e(p.code)}</div></td><td>${money(p.contract)}</td><td>${money(p.budget)}</td><td>${money(p.spent)}</td><td>${money(p.committed)}</td><td class="${remaining<0?'danger-text':'green-text'}"><b>${money(remaining)}</b></td></tr>`}).join('')}</tbody></table></div>`,'','Forecast logic is provisional; no financial ledger integrations are connected')}`;
}
function reportsPage(){const rows=data.projects.map(p=>{const prog=taskProgress(p.id,data.tasks);const done=data.tasks.filter(t=>t.projectId===p.id&&t.status==='Done').length;return `<div class="bar-group"><div class="bar-label"><span>${e(p.name)}</span><span>${prog}% · ${done} completed</span></div>${meter(prog)}</div>`}).join('');const states=['Done','In progress','Ready','Blocked','Inspection','Backlog'];const counts=states.map(s=>data.tasks.filter(t=>t.status===s).length);const max=Math.max(...counts,1);
  return head('Reports & progress','See workload, completed jobs and project milestones across customers.',button(`${ico('refresh')} Refresh view`,'refresh',''))+`<div class="grid-even">${card('Project completion',`<div class="card-body" style="padding-top:0">${rows}</div>`,'','Internal task-derived progress')}${card('Production job pipeline',`<div class="card-body" style="padding-top:0"><div class="report-chart"><div class="skeleton-chart">${counts.map((count,i)=>`<div class="bar" style="height:${Math.max(9,count/max*100)}%"><span>${e(states[i].split(' ')[0])}</span></div>`).join('')}</div></div><p class="form-hint">${data.tasks.length} tracked department jobs across ${data.projects.length} projects.</p></div>`,'','Task statuses across the workshop')}</div>${card('Recent audit history',`<div class="table-wrap"><table class="table"><thead><tr><th>Action</th><th>Description</th><th>Actor</th><th>Time</th></tr></thead><tbody>${data.audit.slice(0,20).map(a=>`<tr><td><b>${e(a.action)}</b></td><td>${e(a.detail)}</td><td>${e(a.actor)}</td><td>${day(a.at)}</td></tr>`).join('')}</tbody></table></div>`,'','Event records for this browser-based demo')}`;
}
function settingsPage(){return head('Workspace settings','Your Project Hub experience and development-stage safeguards.')+`<div class="grid-even">${card('Appearance',`<div class="card-body"><div class="split-header"><div><b>Display theme</b><p class="form-hint">Choose a clean, light workspace or dark mode.</p></div>${button(data.settings.theme==='light'?`${ico('moon')} Dark mode`:`${ico('sun')} Light mode`,'theme','soft')}</div></div>`)}${card('Demo environment',`<div class="card-body"><b>No production connection</b><p class="form-hint">Your changes are stored in this browser. There is no login, database connection, email provider, file upload storage or shared access. This demo is suitable for product evaluation only.</p>${button(`${ico('refresh')} Reset demo data`,'reset-demo','danger')}</div>`)}${card('Email delivery',`<div class="card-body"><b>Disabled by design</b><p class="form-hint">No sending account has been approved. Approval events and invitations remain in the on-screen demo. We will enable email only after isolating and verifying a no-additional-cost route.</p>${badge('Not configured','amber')}</div>`)}${card('Production readiness',`<div class="card-body">${['Customer login & RLS','Private document storage','Secure staff invitations','Transactional stock allocation','Automated emails','Independent deployment'].map(x=>`<div class="pipeline-item"><span class="pipe-main"><strong>${e(x)}</strong></span>${badge('Pending','amber')}</div>`).join('')}</div>`,'','These features require a separately approved backend') }</div>`;
}
function optionList(entries,current){return entries.map(([val,label])=>`<option value="${e(val)}" ${val===current?'selected':''}>${e(label)}</option>`).join('')}
const field=(label,name,kind='text',value='',required=true,extra='')=>`<div class="field"><label for="form-${name}">${e(label)}</label><input id="form-${name}" name="${e(name)}" type="${kind}" value="${e(value)}" ${required?'required':''} ${extra}/></div>`;
const selectField=(label,name,options,current)=>`<div class="field"><label for="form-${name}">${e(label)}</label><select id="form-${name}" name="${e(name)}" required>${optionList(options,current)}</select></div>`;
const textareaField=(label,name,value='')=>`<div class="field full"><label for="form-${name}">${e(label)}</label><textarea id="form-${name}" name="${e(name)}">${e(value)}</textarea></div>`;
function modalContent(){const m=ui.modal||{};let title='Project Hub',form='',hint='',submit='Save';
  if(m.type==='project'){
    title='Create a new project';submit='Create project';
    form=`<div class="form-grid">${field('Project name','name')}${selectField('Customer organisation','orgId',data.organizations.map(o=>[o.id,o.name]),data.organizations[0]?.id)}${selectField('Project template','template',['Bespoke Simulator','King Air 360','DA62','Generic Cockpit','Motion Upgrade'].map(x=>[x,x]),'Bespoke Simulator')}${field('Target delivery','due','date','2027-06-30')}${field('Project budget (EUR)','budget','number','0')}${field('Contract value (EUR)','contract','number','0')}${field('Internal project lead','lead','text','Sim-Worx Project Manager')}${textareaField('Project scope / summary','description')}</div>`;
    hint='The chosen template generates a separate project section hierarchy. Every project has its own customer and scope.';
  }else if(m.type==='customer'){
    title='Create customer organisation';submit='Add customer';
    form=`<div class="form-grid">${field('Company name','name')}${field('Customer code','code','text','')}${field('Country / location','contact','text','')}${field('Brand colour','accent','color','#5369c4')}</div>`;
    hint='New customer organisations are independent. Additional staff and projects can be added after creation.';
  }else if(m.type==='task'){
    title='Assign a new department job';submit='Create job';const projectId=m.project||ui.project||data.projects[0].id;const sections=data.sections.filter(x=>x.projectId===projectId);
    form=`<div class="form-grid">${field('Job title','title')}${selectField('Project','projectId',data.projects.map(p=>[p.id,`${p.code} · ${p.name}`]),projectId).replace('name="projectId"','name="projectId" data-filter="modalProject"')}${selectField('Work section','sectionId',sections.map(s=>[s.id,s.name]),sections[0]?.id)}${selectField('Department','department',['Office','Workshop','Purchasing','Quality'].map(x=>[x,x]),'Workshop')}${field('Assigned to','assignee','text','Unassigned')}${selectField('Priority','priority',['Normal','High','Critical'].map(x=>[x,x]),'Normal')}${field('Due date','due','date',today())}</div>`;
    hint='Jobs can be reassigned and moved through the production board.';
  }else if(m.type==='stock'){
    title='Record stock movement';submit='Record movement';const partId=m.id||data.parts[0]?.id;
    form=`<div class="form-grid">${selectField('Part','partId',data.parts.map(p=>[p.id,`${p.code} · ${p.name}`]),partId)}${selectField('Movement type','type',[['receipt','Receive into stores'],['issue','Issue from stores'],['adjust-in','Positive adjustment'],['adjust-out','Negative adjustment']],'receipt')}${field('Quantity','quantity','number','1',true,'min="1" step="1"')}</div>`;
    hint='Inventory movements are recorded in local demo history. Stock cannot become negative through the demo controls.';
  }else if(m.type==='po'){
    title='New purchase order';submit='Create PO';
    form=`<div class="form-grid">${selectField('Project','projectId',data.projects.map(p=>[p.id,`${p.code} · ${p.name}`]),ui.project)}${selectField('Part','partId',data.parts.map(p=>[p.id,`${p.code} · ${p.name}`]),data.parts[0]?.id)}${field('Supplier','supplier','text','')}${field('Quantity','quantity','number','1',true,'min="1" step="1"')}${field('Price each (EUR)','unitCost','number','0',true,'min="0" step="0.01"')}</div>`;
    hint='One-line purchase orders are available in this demonstration. Multi-line purchasing and partial deliveries are planned for the secure backend.';
  }else if(m.type==='invite'){
    title='Add customer staff';submit='Create demo invitation';const orgId=m.org||ui.clientOrg;const projects=data.projects.filter(p=>p.orgId===orgId);
    form=`<input type="hidden" name="orgId" value="${e(orgId)}"/><div class="form-grid">${field('Full name','name')}${field('Work email','email','email')}${selectField('Client role','role',['Client Viewer','Client Engineer','Client Approver','Client Lead'].map(x=>[x,x]),'Client Viewer')}${selectField('Project access','projectId',projects.map(p=>[p.id,p.name]),projects[0]?.id)}</div>`;
    hint='This is a mock invitation only; no email is sent. Production permissions will be restricted to the customer admin’s delegated project ceilings.';
  }else if(m.type==='update'){
    title='Prepare customer progress update';submit='Save draft';
    form=`<input type="hidden" name="projectId" value="${e(m.project||ui.project)}"/><div class="form-grid">${field('Public update title','title')}${selectField('Update category','kind',['Milestone','Component','Manufacturing','Quality','Delivery'].map(x=>[x,x]),'Milestone')}${field('Related component','part','text','',false)}${textareaField('Customer-facing summary','description')}</div>`;
    hint='Drafts remain internal. A separate publish action is required before customers can see an update.';
  }else if(m.type==='document'||m.type==='client-document'){
    const client=m.type==='client-document';title=client?'Customer drawing / document':'Register internal document';submit='Save document metadata';
    form=`<input type="hidden" name="projectId" value="${e(client?ui.clientProject:(m.project||ui.project))}"/><div class="form-grid">${field('Document name','title')}${field('Revision','rev','text','A')}${selectField('Document category','type',['PDF drawing','Inspection report','Photo','CAD file','Other document'].map(x=>[x,x]),'PDF drawing')}${!client?selectField('Visibility','visibility',[['internal','Internal only'],['customer','Published to client']],'internal'):''}</div>`;
    hint='Only descriptive metadata is saved locally. No document bytes are uploaded. Secure uploads require authenticated private storage.';
  }else if(m.type==='notifications'){
    title='Notifications';submit='Close';form=`<div>${data.notifications.map(n=>`<div class="approval-row"><div><strong>${e(n.text)}</strong><small>${day(n.date)}</small></div>${badge(n.read?'Read':'New',n.read?'gray':'purple')}</div>`).join('')||'<p class="subtle">No notifications</p>'}</div>`;
  }
  return `<div class="modal-backdrop" role="presentation" data-action="dismiss-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${e(title)}</h2><button class="circle-btn" type="button" data-action="close-modal" aria-label="Close modal">${ico('close')}</button></div><form data-form="${e(m.type)}"><div class="modal-body">${form}${hint?`<p class="form-hint">${e(hint)}</p>`:''}</div><div class="form-foot">${button('Cancel','close-modal')}${m.type==='notifications'?button('Mark all read','mark-read','primary'):`<button class="btn primary" type="submit">${e(submit)} ${ico('arrow')}</button>`}</div></form></div></div>`;
}
function openModal(type,details={}){ui.modal={type,...details};render()}
function closeModal(){ui.modal=null;render()}
function changePage(page){ui.page=page;ui.modal=null;render()}
function handleAction(el){const action=el.dataset.action,id=el.dataset.id;
 try{switch(action){
  case 'nav':changePage(id);break;
  case 'project-open':ui.page='projects';ui.project=id;ui.projectTab='structure';render();document.getElementById('project-detail')?.scrollIntoView({behavior:'smooth',block:'start'});break;
  case 'project-tab':ui.projectTab=id;render();break;
  case 'client-tab':ui.clientTab=id;render();break;
  case 'task-board':ui.taskView='board';render();break;
  case 'task-list':ui.taskView='list';render();break;
  case 'department-open':ui.dept=id;ui.page='tasks';render();break;
  case 'open-project-modal':openModal('project');break;
  case 'open-task-modal':openModal('task',{project:el.dataset.project||ui.project});break;
  case 'open-customer-modal':openModal('customer');break;
  case 'open-po-modal':openModal('po');break;
  case 'stock-modal':openModal('stock',{id});break;
  case 'invite-modal':openModal('invite',{org:el.dataset.org||ui.clientOrg});break;
  case 'open-update-modal':openModal('update',{project:el.dataset.project||ui.project});break;
  case 'open-document-modal':openModal('document',{project:el.dataset.project||ui.project});break;
  case 'open-client-document-modal':openModal('client-document');break;
  case 'customer-detail':ui.customerDetail=id;render();break;
  case 'close-modal':case 'dismiss-modal':closeModal();break;
  case 'theme':data.settings.theme=data.settings.theme==='light'?'dark':'light';persist();render();break;
  case 'toggle-task':{const t=data.tasks.find(x=>x.id===id);if(t){t.status=t.status==='Done'?'Ready':'Done';audit('Job status updated',`${t.title} → ${t.status}`);persist();render();toast('Job status saved locally')}break;}
  case 'publish':{publishUpdate(data,id);persist();render();toast('Update published to the demo customer portal');break;}
  case 'decide-approval':{decideApproval(data,id,el.dataset.decision);notify(`Client decision: ${el.dataset.decision}`);persist();render();toast(`Decision recorded: ${el.dataset.decision}`);break;}
  case 'receive-po':{receiveOrder(data,id);persist();render();toast('Outstanding purchase order quantities received into stock');break;}
  case 'notifications':openModal('notifications');break;
  case 'mark-read':data.notifications.forEach(x=>x.read=true);persist();closeModal();toast('Notifications marked as read');break;
  case 'reset-demo':if(confirm('Reset all local demo records and changes? This cannot be undone.')){data=seed();persist();ui.page='overview';ui.project='p1';ui.clientOrg='noah';ui.clientProject='p1';render();toast('Demo reset to original sample data')}break;
  case 'refresh':render();toast('Dashboard refreshed from local demo records');break;
  }}catch(err){toast(err.message||'Unable to complete this action',true)}
}
function formHandler(form){const fd=new FormData(form);const get=n=>String(fd.get(n)||'').trim();const type=form.dataset.form;
 try{switch(type){
  case 'project':{const id=uid('p');const org=findOrg(get('orgId'));if(!org)throw Error('Please select a customer');const name=get('name');if(!name)throw Error('Enter a project name');const template=get('template');const code=`SW-${String(new Date().getFullYear()).slice(-2)}${String(data.projects.length+45).padStart(3,'0')}`;data.projects.unshift({id,orgId:org.id,name,code,template,status:'Design',phase:'Engineering',due:get('due'),budget:Number(get('budget'))||0,contract:Number(get('contract'))||0,spent:0,committed:0,publishedProgress:0,lead:get('lead'),description:get('description')||name,created:today()});const sections=template==='DA62'?['Cockpit','Visual system','Avionics','Testing & delivery']:template==='Motion Upgrade'?['Mechanics','Control systems','Installation & test']:['Cockpit & structure','Control loading','Visual system','Avionics & software','Testing & delivery'];sections.forEach(s=>data.sections.push({id:uid('s'),projectId:id,name:s,weight:Math.round(100/sections.length)}));audit('Project created',`${code} for ${org.name}`);ui.project=id;ui.page='projects';ui.projectTab='structure';break;}
  case 'customer':{const name=get('name'),code=get('code').toUpperCase();if(!name||!code)throw Error('Enter customer name and code');if(data.organizations.some(o=>o.code===code))throw Error('Customer code already exists');const accent=/^#[a-f0-9]{6}$/i.test(get('accent'))?get('accent'):'#5369c4';const orgId=uid('org');data.organizations.push({id:orgId,name,code,accent,contact:get('contact'),logo:name[0]?.toUpperCase()||'C'});ui.customerDetail=orgId;ui.page='customers';audit('Customer created',name);break;}
  case 'task':{const projectId=get('projectId');const sec=data.sections.find(s=>s.id===get('sectionId')&&s.projectId===projectId);if(!sec)throw Error('Choose a section belonging to the selected project');data.tasks.push({id:uid('t'),projectId,sectionId:sec.id,title:get('title'),department:get('department'),assignee:get('assignee'),priority:get('priority'),status:'Backlog',due:get('due')});audit('Job created',get('title'));ui.page='tasks';break;}
  case 'stock':{stockMove(data,{partId:get('partId'),quantity:get('quantity'),type:get('type')});ui.page='inventory';break;}
  case 'po':{const part=findPart(get('partId'));if(!part)throw Error('Part not found');const q=Number(get('quantity')),cost=Number(get('unitCost'));if(!Number.isInteger(q)||q<1||!Number.isFinite(cost)||cost<0)throw Error('Check order quantity and unit cost');const code=`PO-${new Date().getFullYear().toString().slice(2)}${String(data.orders.length+120).padStart(4,'0')}`;data.orders.unshift({id:uid('po'),code,projectId:get('projectId'),supplier:get('supplier')||part.supplier,date:today(),status:'Awaiting delivery',items:[{partId:part.id,quantity:q,received:0,unitCost:cost}]});audit('Purchase order created',code);ui.page='purchasing';break;}
  case 'invite':{clientInvite(data,{orgId:get('orgId'),name:get('name'),email:get('email'),role:get('role'),projectIds:[get('projectId')]});ui.page=ui.page==='client'?'client':'customers';break;}
  case 'update':{data.updates.unshift({id:uid('u'),projectId:get('projectId'),title:get('title'),kind:get('kind'),part:get('part'),description:get('description'),date:today(),status:'draft'});audit('Customer update drafted',get('title'));ui.page='projects';ui.project=get('projectId');ui.projectTab='publishing';break;}
  case 'document':case 'client-document':{data.documents.unshift({id:uid('d'),projectId:get('projectId'),title:get('title'),rev:get('rev'),type:get('type'),visibility:type==='client-document'?'internal':get('visibility'),date:today()});audit(type==='client-document'?'Customer document metadata submitted':'Document registered',get('title'));break;}
  case 'message':{const text=get('text');if(!text)throw Error('Enter a message');data.messages.push({id:uid('msg'),projectId:ui.clientProject,author:'Customer demo user',text,visibility:'customer',at:new Date().toISOString()});audit('Customer message drafted',`Message in ${ui.clientProject}`);break;}
  default:return;
 }ui.modal=null;persist();render();toast(type==='invite'?'Demo invitation recorded — no email sent':type==='client-document'?'Metadata saved for internal review — no file uploaded':'Saved to local demo workspace');
 }catch(err){toast(err.message||'Unable to save form',true)}
}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(el){if(el.dataset.action==='dismiss-modal'&&ev.target!==el)return;handleAction(el)}});
document.addEventListener('submit',ev=>{const form=ev.target.closest('form[data-form]');if(form){ev.preventDefault();formHandler(form)}});
document.addEventListener('change',ev=>{const el=ev.target;const filter=el.dataset.filter;
 if(filter==='dept'){ui.dept=el.value;render()}
 else if(filter==='taskProject'){ui.taskProject=el.value;render()}
 else if(filter==='clientOrg'){ui.clientOrg=el.value;ui.clientProject=data.projects.find(p=>p.orgId===el.value)?.id;ui.clientTab='updates';render()}
 else if(filter==='clientProject'){ui.clientProject=el.value;render()}
 else if(filter==='modalProject'){ui.modal.project=el.value;render()}
 else if(el.dataset.taskStatus){const task=data.tasks.find(t=>t.id===el.dataset.taskStatus);if(task){task.status=el.value;audit('Job status updated',`${task.title}: ${el.value}`);persist();render();toast('Job status updated')}}
});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&ui.modal)closeModal()});
render();